function startPractice(activityId){activeActivityId=activityId;practiceFeedback=null;render()}
function submitPractice(event){event.preventDefault();const form=event.currentTarget,activity=pedagogy.activities.find(a=>a.id===form.dataset.activity);if(!activity)return;const values=new FormData(form),rawAnswer=String(values.get("answer")||"").trim(),confidence=Number(values.get("confidence")||3);if(!rawAnswer){toast("Registre uma resposta antes de concluir.");return}let answer=rawAnswer,correct=null,outcome="self-assessed";if(activity.type==="choice"){const selected=Number(rawAnswer);answer=activity.options[selected]||rawAnswer;correct=selected===activity.correctIndex;outcome=correct?"correct":"incorrect"}else if(activity.type==="boolean"){answer=rawAnswer==="true"?"Verdadeiro":"Falso";correct=(rawAnswer==="true")===activity.correctBoolean;outcome=correct?"correct":"incorrect"}else{outcome=String(values.get("selfAssessment")||"");if(!["complete","partial","review"].includes(outcome)){toast("Registre sua autoavaliação.");return}}const attempt={id:id(),activityId:activity.id,activityVersion:activity.version||1,answer,correct,outcome,confidence,completedAt:new Date().toISOString()};pedagogy.attempts.push(attempt);practiceFeedback={activity,attempt};activeActivityId=null;savePedagogy();render();toast("Tentativa registrada no histórico.") }
function studyMaterialPlainText(raw,format){
 let text=String(raw||"");
 if(format==="html"||format==="htm"){const doc=new DOMParser().parseFromString(text,"text/html");doc.querySelectorAll("script,style,noscript,svg").forEach(n=>n.remove());text=doc.body.textContent||""}
 if(format==="tex"){text=text.replace(/\\(?:sub)*section\*?\{([^}]+)\}/g,"\n\n### $1\n").replace(/\\(?:begin|end)\{[^}]+\}/g,"\n").replace(/\\(?:title|author|date)\{([^}]+)\}/g,"$1\n").replace(/\\url\{([^}]+)\}/g,"$1").replace(/\\href\{([^}]+)\}\{([^}]+)\}/g,"$2 ($1)").replace(/\\[a-zA-Z]+\*?(?:\[[^\]]*\])?/g," ").replace(/[{}]/g," ")}
 return text.replace(/\r\n?/g,"\n").replace(/[ \t]+\n/g,"\n").replace(/\n{3,}/g,"\n\n").trim();
}
function studyMaterialImportText(raw,format){
 if(format==="json"){try{const parsed=JSON.parse(raw);if(parsed?.format==="estudos-research-export"&&Array.isArray(parsed.records))return parsed.records.map((r,i)=>["## "+(r.title||"Fonte "+(i+1)),"Fonte: "+(r.provider||""),"Autoria: "+(r.authors||""),"Ano: "+(r.year||""),r.description||"",r.url||""].filter(Boolean).join("\n")).join("\n\n");}catch(e){throw new Error("O JSON não é válido.")}}
 return studyMaterialPlainText(raw,format);
}
function studyMaterialSections(material){
 const text=String(material.plainText||studyMaterialPlainText(material.content,material.format)),lines=text.split("\n"),sections=[];let title="",buffer=[];
 const flush=()=>{const body=buffer.join("\n").trim();if(body.length>=35){for(let i=0;i<body.length;i+=4500)sections.push({title:title||"Trecho "+(sections.length+1),text:body.slice(i,i+4500).trim()})}buffer=[]};
 for(const line of lines){const trimmed=line.trim(),heading=trimmed.match(/^(#{1,6})\s+(.+)$/);if(heading){flush();title=heading[2].trim();continue}if(trimmed)buffer.push(trimmed);else if(buffer.length&&buffer[buffer.length-1]!=="")buffer.push("")}
 flush();if(!sections.length&&text.length)for(let i=0;i<text.length;i+=4500)sections.push({title:"Trecho "+(sections.length+1),text:text.slice(i,i+4500).trim()});
 return sections;
}
function studyMaterialPanel(){
 const materials=data.studyMaterials||[],courseOptions='<option value="">Sem curso específico</option>'+data.courses.map(c=>'<option value="'+esc(c.id)+'">'+esc(c.title)+'</option>').join("");
 return '<section class="panel study-material-panel"><header><div><small class="eyebrow">CONHECIMENTO DE REFERÊNCIA</small><h2>Materiais de estudo</h2></div><span class="pill">'+materials.length+'</span></header><p>Importe a pesquisa que você reuniu fora do app. O conteúdo vira uma fonte consultável para elaborar atividades, sem precisar processar o documento inteiro de uma vez.</p><form id="study-material-import-form" class="study-material-form"><label>Título do material<input name="title" maxlength="120" placeholder="Ex.: Fundamentos de logística empresarial"></label><label>Vincular a um curso<select name="courseId">'+courseOptions+'</select></label><label>Arquivo de pesquisa<input name="file" type="file" accept=".txt,.md,.markdown,.tex,.html,.htm,.csv,.json,.bib,.ris,.pdf,.docx,text/plain,text/markdown,text/html,application/json"></label><div class="study-material-or">ou cole o conteúdo abaixo</div><label>Texto da pesquisa<textarea name="content" rows="5" placeholder="Cole aqui o texto da pesquisa, resumo, fichamento ou conteúdo exportado."></textarea></label><small class="muted">Texto sem limite artificial por arquivo ou quantidade de materiais. O conteúdo fica neste dispositivo, em armazenamento IndexedDB separado dos dados gerais. PDF e DOCX são identificados, mas ainda não têm extração de texto integrada.</small><div id="study-material-diagnostics" class="study-material-diagnostics '+(studyMaterialDiagnostic?.kind||"")+'" role="status" aria-live="polite" '+(studyMaterialDiagnostic?"":"hidden")+'>'+(studyMaterialDiagnostic?esc(studyMaterialDiagnostic.message+(studyMaterialDiagnostic.details?" "+studyMaterialDiagnostic.details:"")):"")+'</div><button class="primary" type="submit">＋ Importar material</button></form>'+(materials.length?'<div class="study-material-list">'+materials.map(m=>{const sections=studyMaterialSections(m),linkedObjectives=pedagogy.objectives.filter(o=>o.courseId===m.courseId);return '<article class="study-material-card"><header><div><strong>'+esc(m.title)+'</strong><small>'+esc(m.sourceName||m.format.toUpperCase())+' · '+sections.length+' trechos · '+(m.characters||0).toLocaleString("pt-BR")+' caracteres</small><small>'+esc(data.courses.find(c=>c.id===m.courseId)?.title||"Sem curso vinculado")+'</small></div><button class="link danger" data-delete-study-material="'+m.id+'">Excluir</button></header>'+(m.courseId&&!linkedObjectives.length?'<p class="muted">Este curso ainda não tem objetivos de aprendizagem.</p><button class="secondary" data-action="new-objective-from-material" data-material="'+m.id+'">＋ Criar objetivo para este material</button>':'')+'<div class="study-material-sections">'+sections.slice(0,12).map((s,i)=>'<div class="study-material-section"><span><b>'+esc(s.title)+'</b><small>'+esc(s.text.slice(0,210))+(s.text.length>210?"…":"")+'</small></span><button class="secondary" data-action="activity-from-material" data-material="'+m.id+'" data-section="'+i+'" '+(!linkedObjectives.length?'disabled':'')+'>Criar atividade</button></div>').join("")+'</div>'+(sections.length>12?'<small class="muted">Exibindo os 12 primeiros trechos de '+sections.length+'. O conteúdo completo permanece guardado.</small>':'')+'</article>'}).join("")+'</div>':'<p class="muted">Nenhum material importado ainda.</p>')+'</section>';
}
async function importStudyMaterial(event){
 event.preventDefault();const form=event.currentTarget,values=new FormData(form),file=values.get("file"),pasted=String(values.get("content")||"").trim();
 if(!studyMaterialStorageReady){studyMaterialReport("Importação interrompida: o armazenamento local de materiais não foi inicializado.","Verifique o armazenamento do navegador e recarregue o app.","error");return}
 if(file&&file.size&&pasted){studyMaterialReport("Importação não realizada: há um arquivo e um texto colado ao mesmo tempo.","Escolha apenas uma das duas entradas.","warning");return}
 if((!file||!file.size)&&!pasted){studyMaterialReport("Nenhum conteúdo recebido.","Selecione um arquivo de texto ou cole o conteúdo no campo.","warning");return}
 let raw="",format="txt",sourceName="Texto colado",stage="leitura";
 try{
  if(file&&file.size){sourceName=file.name;format=(file.name.split(".").pop()||"txt").toLowerCase();if(format==="pdf"||format==="docx")throw new Error("O arquivo "+format.toUpperCase()+" foi reconhecido, mas este importador ainda não extrai texto desse formato. Exporte o documento como TXT, Markdown ou HTML.");if(!["txt","md","markdown","tex","html","htm","csv","json","bib","ris"].includes(format))throw new Error("Formato não suportado: ."+format+". Formatos aceitos: TXT, MD, TEX, HTML, CSV, JSON, BIB e RIS.");raw=await file.text()}else raw=pasted;
  stage="conversão";const plainText=studyMaterialImportText(raw,format);if(!plainText.trim())throw new Error("O arquivo foi lido, mas não produziu texto. Pode conter apenas imagens, elementos não textuais ou marcação removida durante a conversão.");if(plainText.trim().length<35)throw new Error("O conteúdo extraído possui apenas "+plainText.trim().length+" caracteres. São necessários pelo menos 35 caracteres para criar trechos de estudo.");
  const material={id:id(),title:String(values.get("title")||"").trim()||sourceName.replace(/\.[^.]+$/,"")||"Material de estudo",sourceName,format,content:raw,plainText,courseId:String(values.get("courseId")||""),characters:plainText.length,createdAt:new Date().toISOString()};
  stage="gravação IndexedDB";await putStudyMaterialRecord(material);data.studyMaterials||=[];data.studyMaterials.push(material);
  if(!save()){data.studyMaterials.pop();await deleteStudyMaterialRecord(material.id);throw new Error("O material foi gravado, mas os dados gerais não puderam ser salvos. A gravação parcial foi revertida.")}
  form.reset();render();const info=await studyMaterialStorageInfo();studyMaterialReport("Importação concluída: "+plainText.length.toLocaleString("pt-BR")+" caracteres extraídos. "+studyMaterialSections(material).length+" trechos criados.",info,"success");toast("Material importado e pronto para virar atividade.");
 }catch(error){const detail="Etapa: "+stage+". Arquivo: "+sourceName+". "+(file&&file.size?"Tamanho: "+file.size.toLocaleString("pt-BR")+" bytes. ":"")+"Diagnóstico: "+studyMaterialErrorMessage(error);studyMaterialReport("Falha na importação.",detail,"error");console.error("Study material import failed:",{stage,sourceName,fileSize:file?.size,error});toast("Falha ao importar material. Consulte o diagnóstico exibido no formulário.")}
}
function createActivityFromMaterial(materialId,sectionIndex){
 const material=(data.studyMaterials||[]).find(m=>m.id===materialId);if(!material)return;
 const scoped=material.courseId?pedagogy.objectives.filter(o=>o.courseId===material.courseId):pedagogy.objectives;
 if(!scoped.length){toast("Crie primeiro um objetivo de aprendizagem vinculado ao curso deste material.");return}
 const section=studyMaterialSections(material)[Number(sectionIndex)];if(!section){toast("Trecho não encontrado.");return}
 const topic=section.title.startsWith("Trecho ")?section.text.split(/[.!?]\s/)[0].slice(0,110):section.title;
 const draft={type:"written",title:"Explicar: "+topic.slice(0,95),prompt:"Sem consultar o material, explique com suas palavras: "+topic+". Apresente os conceitos centrais, suas relações e um exemplo coerente com o conteúdo estudado.",modelAnswer:section.text,rubric:"A resposta deve apresentar os conceitos centrais do trecho, explicar as relações entre eles e evitar apenas reproduzir frases sem demonstrar compreensão.",sourceMaterialId:material.id,sourceSectionTitle:section.title,sourceExcerpt:section.text};
 newActivity(scoped[0].id,scoped,draft);
}
